def find_good_sequences_refined(n):
    import itertools

    good_sequences = []
    # All sequences a of length n+1 with sum n+1 and a_i in {0, ..., n}
    # Since n is small, we can use product or a more efficient way.
    # Actually, the number of such sequences is not too large for small n.

    # For n=4, sum=5, a_i in {0,1,2,3,4}, sequence length 5.
    # The number of such sequences is the number of ways to put 5 items into 5 bins = 5^5 = 3125.
    # This is very small.

    for a in itertools.product(range(n + 1), repeat=n + 1):
        if sum(a) == n + 1:
            b = [0] * (n + 1)
            for x in a:
                b[x] += 1
            if sum(b) == n + 1:
                a_prime = [0] * (n + 1)
                for x in b:
                    a_prime[x] += 1
                if a_prime == list(a):
                    good_sequences.append(list(a))
    return good_sequences

