def find_all_sums(n):
    import itertools
    results = []
    for c in itertools.product(range(n + 1), repeat=n + 1):
        c = list(c)
        if sum(c) == n + 1 and sum(i * c[i] for i in range(n + 1)) == n + 1:
            valid = True
            for k in range(n + 1):
                if c.count(k) != c[k]:
                    valid = False
                    break
            if valid:
                # Sum = Sum(c_k * (k+1) * k^2)
                s = sum(c[k] * (k + 1) * (k**2) for k in range(n + 1))
                results.append(s)
    return sorted(list(set(results)))

